class Solution {
public:
    int takeCharacters(string s, int k) {
        int n = s.size();
        int total[3] = {0, 0, 0};
        for (char c : s) total[c - 'a']++;
        for (int i = 0; i < 3; i++) {
            if (total[i] < k) return -1;
        }
        int limit[3];
        for (int i = 0; i < 3; i++) limit[i] = total[i] - k;
        int cnt[3] = {0, 0, 0};
        int left = 0, best = 0;
        for (int right = 0; right < n; right++) {
            int idx = s[right] - 'a';
            cnt[idx]++;
            while (cnt[idx] > limit[idx]) {
                cnt[s[left] - 'a']--;
                left++;
            }
            if (right - left + 1 > best) best = right - left + 1;
        }
        return n - best;
    }
};
